        for (let sell = 0; sell < n; sell++) {
            if (buy === sell) continue;

            const buyPlanet = planets[buy];
            const sellPlanet = planets[sell];

            // DP: dp[t] = max profit using exactly t items (or at most t items)
            // We'll use dp[t] = max profit with total items = t
            // Initialize with -infinity, dp[0] = 0

