                // Actually, if profitPerItem <= 0, buying it reduces profit or doesn't help. So skip.
                if (profitPerItem <= 0) continue;

                // Bounded knapsack: we can take 0 to maxCount items of this type.
                // We can use the standard technique: for each item type, iterate t from k down to 0,
