                // But this is O(k * maxCount * m) which is 100 * 100 * 100 = 1e6 per pair, and n^2 = 100 pairs, so 1e8 which might be too slow in JS.

                // Better: use the binary decomposition or the "multiple knapsack" optimization.
                // Alternatively, since k is small (100), we can do:
                // For each t from k down to 0:
                //   for q from 1 to min(maxCount, k - t):
                //       dp[t + q] = max(dp[t + q], dp[t] + q * profitPerItem)
                // This is O(k * maxCount) per item type, so O(k * maxCount * m) = 100 * 100 * 100 = 1e6 per pair.
                // 100 pairs * 1e6 = 1e8 operations. Might be borderline in JS.

                // Let's try a different approach: since each item has weight 1, we can think of it as:
                // We have m types, each with a profit per item and a max count.
                // We want to pick up to k items total to maximize profit.
                // This is equivalent to: we have a multiset of items where item type j has maxCount copies, each with value profitPerItem.
                // We want to pick up to k items with max total value.
                // So we can just collect all possible items (with their values), sort them in descending order, and take the top k.
                // But we can't take more than maxCount of each type.

                // So: for this pair, create a list of all items we could potentially buy.
                // For each type j, we have up to maxCount items, each with value profitPerItem.
                // We want to pick up to k items from this list to maximize sum.
                // So we can just sort all items by value descending and take the first k.

                // But generating all items: total items = sum of maxCount over j, which can be up to m * 100 = 100 * 100 = 10000.
                // Sorting 10000 items is fine.

                // Let's do that.
                const allItems = [];
                for (let j = 0; j < m; j++) {
                    const profitPerItem = sellPlanet.items[j].b - buyPlanet.items[j].a;
                    const maxCount = buyPlanet.items[j].c;
                    if (profitPerItem > 0 && maxCount > 0) {
                        for (let q = 0; q < maxCount; q++) {
                            allItems.push(profitPerItem);
                        }
                    }
                }

                // Sort in descending order
                allItems.sort((a, b) => b - a);

                // Take up to k items
                let totalProfit = 0;
                for (let t = 0; t < Math.min(k, allItems.length); t++) {
                    totalProfit += allItems[t];
                }

                if (totalProfit > maxProfit) {
                    maxProfit = totalProfit;
                }
            }
        }
    }

    console.log(maxProfit);
}
