function solve(n, m, k, planets) {
    // For each pair of planets (buy planet i, sell planet j), i != j
    // We want to maximize profit by buying items on planet i and selling on planet j
    // For each item type j, profit per unit = b[j][sellPlanet] - a[j][buyPlanet]
    // We can buy at most c[j][buyPlanet] items of type j on buyPlanet
    // Total items bought <= k

    // This is a bounded knapsack problem where:
    // - We have m item types
    // - For each type, we can buy 0 to c items
    // - Each item has a profit (which could be negative, so we'd skip it)
    // - Total items <= k
    // - Maximize total profit

    let maxProfit = 0;

    for (let buyPlanet = 0; buyPlanet < n; buyPlanet++) {
        for (let sellPlanet = 0; sellPlanet < n; sellPlanet++) {
            if (buyPlanet === sellPlanet) continue;

            // Calculate profit for each item type
            const profits = [];
            const maxCounts = [];
            for (let j = 0; j < m; j++) {
                const buyCost = planets[buyPlanet].items[j].a;
                const sellPrice = planets[sellPlanet].items[j].b;
                const maxCount = planets[buyPlanet].items[j].c;
                const profit = sellPrice - buyCost;
                profits.push(profit);
                maxCounts.push(maxCount);
            }

            // Bounded knapsack: dp[t] = max profit using exactly t items
            // Or dp[t] = max profit using at most t items
            // Let's use dp[t] = max profit with t items total
            // Initialize with -infinity, dp[0] = 0
            const dp = new Array(k + 1).fill(-Infinity);
            dp[0] = 0;

            // For each item type, we can take 0 to maxCount[j] items
            // This is a bounded knapsack. We can use the standard approach:
            // For each item type, iterate from k down to 0, and for each possible count
            // But that's O(m * k * maxCount) which could be 100 * 100 * 100 = 1e6, acceptable

            // Better approach: use the "multiple knapsack" technique
            // For each item type j with profit p and max count c:
            // We can decompose c into powers of 2
            // Or simply iterate

            // Let's do it directly: for each item type, update dp
            // dp_new[t] = max over x from 0 to min(c, t) of dp_old[t-x] + x*p
            // But this is O(m * k * c) worst case

            // Since m, k, c are all <= 100, O(m * k * c) = 100*100*100 = 1e6 per planet pair
            // And there are at most n*(n-1) = 90 planet pairs
            // Total: 90 * 1e6 = 9e7, might be tight in JS but let's try

            // Actually, let's use a more efficient approach with the standard bounded knapsack
            // using the decomposition into powers of 2

            for (let j = 0; j < m; j++) {
                const p = profits[j];
                const c = maxCounts[j];
                if (p <= 0 || c === 0) continue; // No point in taking items with non-positive profit

                // Decompose c into powers of 2
                const counts = [];
                let remaining = c;
                let power = 1;
                while (remaining > 0) {
                    const take = Math.min(power, remaining);
                    counts.push(take);
                    remaining -= take;
                    power *= 2;
                }

                // Now treat each "group" as a 0/1 knapsack item
                // Group of size 'take' has weight 'take' and value 'take * p'
                // We need to update dp in reverse order for 0/1 knapsack

                // Actually, for bounded knapsack with the power decomposition, we process each group as a 0/1 item
                // But we need to be careful: the standard approach is to process groups in order
                // and for each group, update dp from high to low

                // Let's create a new dp array for this item type
                const newDp = new Array(k + 1).fill(-Infinity);
                for (let t = 0; t <= k; t++) {
                    if (dp[t] === -Infinity) continue;
                    // Try adding each group
                    let used = 0;
                    for (const take of counts) {
                        if (used + take > t) break;
                        const newT = t + take;
                        const newVal = dp[t] + take * p;
                        if (newVal > newDp[newT]) {
                            newDp[newT] = newVal;
                        }
                        used += take;
                    }
                }

                // Merge: dp[t] = max(dp[t], newDp[t])
                for (let t = 0; t <= k; t++) {
                    if (newDp[t] > dp[t]) {
                        dp[t] = newDp[t];
                    }
                }
            }

            // Find max profit
            for (let t = 0; t <= k; t++) {
                if (dp[t] > maxProfit) {
                    maxProfit = dp[t];
                }
            }
        }
    }

    return maxProfit;
}
