function solve(lines) {
    if (lines.length === 0) return;

    const firstLine = lines[0].split(' ').map(Number);
    const n = firstLine[0];
    const m = firstLine[1];
    const k = firstLine[2];

    let index = 1;
    const planets = [];

    for (let i = 0; i < n; i++) {
        // Skip planet name
        index++; // planet name line
        const items = [];
        for (let j = 0; j < m; j++) {
            const parts = lines[index].split(' ').map(Number);
            index++;
            items.push({ a: parts[0], b: parts[1], c: parts[2] });
        }
        planets.push(items);
    }

    // For each pair of planets (buy on i, sell on j), i != j
    // We want to maximize profit with at most k items
    // For each item type, on planet i we can buy up to c_ij items at cost a_ij
    // On planet j we can sell at price b_ij
    // Profit per item of type t bought on i and sold on j = b_jt - a_it
    // We can buy up to c_it items of type t on planet i
    // Total items bought <= k

    // This is a bounded knapsack problem
    // For each pair (i, j), i != j:
    //   For each item type t, we have up to c_it items, each with profit (b_jt - a_it)
    //   We want to select items (up to k total) to maximize total profit
    //   Note: we can also choose not to buy any items (profit 0)

    let maxProfit = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) continue;

            // dp[x] = max profit using exactly x items (or up to x items)
            // Let's use dp[x] = max profit with at most x items
            // Actually, let's use standard knapsack: dp[x] = max profit with exactly x items
            // But we want max over all x from 0 to k

            const dp = new Array(k + 1).fill(-Infinity);
            dp[0] = 0;

            for (let t = 0; t < m; t++) {
                const buyCost = planets[i][t].a;
                const sellPrice = planets[j][t].b;
                const maxCount = planets[i][t].c;
                const profitPerItem = sellPrice - buyCost;

                if (profitPerItem <= 0) {
                    // No point in buying this item type
                    continue;
                }

                // Bounded knapsack: we can take 0 to maxCount items of this type
                // Each item has weight 1 and value profitPerItem
                // Use binary decomposition or simple loop

                // Simple approach: for each possible count from 1 to maxCount
                // But that could be O(k * m * c) which is 100 * 100 * 100 = 1e6 per pair
                // n is at most 10, so pairs are at most 90
                // Total: 90 * 1e6 = 9e7 which might be tight in JS

                // Better: use binary decomposition for bounded knapsack
                // Or use the standard trick: dp_new[x] = max over c=0..min(maxCount, x) of dp_old[x-c] + c*profitPerItem

                // Let's use the binary decomposition method
                const newDp = new Array(k + 1).fill(-Infinity);
                for (let x = 0; x <= k; x++) {
                    newDp[x] = dp[x];
                }

                // Binary decomposition of maxCount
                let remaining = maxCount;
                let power = 1;
                while (remaining > 0) {
                    const take = Math.min(power, remaining);
                    const weight = take;
                    const value = take * profitPerItem;

                    for (let x = k; x >= weight; x--) {
                        if (newDp[x - weight] !== -Infinity) {
                            newDp[x] = Math.max(newDp[x], newDp[x - weight] + value);
                        }
                    }

                    remaining -= take;
                    power *= 2;
                }

                for (let x = 0; x <= k; x++) {
                    dp[x] = newDp[x];
                }
            }

            for (let x = 0; x <= k; x++) {
                if (dp[x] > maxProfit) {
                    maxProfit = dp[x];
                }
            }
        }
    }

    console.log(maxProfit);
}
