            const parts = lines[lineIdx].split(' ').map(Number);
            const [a, b, c] = parts;
            items.push({ a, b, c });
            lineIdx++;
        }
        planets.push({ name, items });
    }

    // For each pair of planets (buy on i, sell on j), i != j
    // We want to maximize profit: sum over items of (sell_price - buy_price) * quantity
    // Subject to: total quantity <= k, and for each item type, quantity <= c_ij (buy limit on planet i)
    // Also, we can choose not to buy any item of a type.

    let maxProfit = 0;

    for (let buyPlanet = 0; buyPlanet < n; buyPlanet++) {
        for (let sellPlanet = 0; sellPlanet < n; sellPlanet++) {
            if (buyPlanet === sellPlanet) continue;

            // For each item type, compute the profit per unit if we buy on buyPlanet and sell on sellPlanet
            // profit_j = b[sellPlanet][j] - a[buyPlanet][j]
            // We can buy up to c[buyPlanet][j] items of type j
            // We want to select quantities x_j such that sum(x_j) <= k, 0 <= x_j <= c[buyPlanet][j]
            // Maximize sum(x_j * profit_j)

            // This is a bounded knapsack problem where each item type has a "profit" per unit and a max count.
            // Since m and k are up to 100, we can use DP.
            // dp[t] = max profit using exactly t items (or up to t items)

            // Actually, let's think: we have m types. For each type j, we can choose x_j in [0, c_j].
            // The total number of items is sum(x_j) <= k.
            // We want to maximize sum(x_j * p_j) where p_j = b_sell[j] - a_buy[j].

            // If p_j <= 0, we won't buy any of type j (since it doesn't give profit).
            // So we only consider types with p_j > 0.

            // This is equivalent to: we have m groups, each group j has c_j identical items each with value p_j.
            // We want to pick at most k items total to maximize total value.

            // Since all items of the same type have the same value, the optimal strategy is:
            // Sort the types by p_j in descending order. Then take as many as possible from the highest p_j first.

            const profits = [];
            for (let j = 0; j < m; j++) {
                const p = planets[sellPlanet].items[j].b - planets[buyPlanet].items[j].a;
