            profits.sort((x, y) => y.p - x.p);

            let totalItems = 0;
            let currentProfit = 0;
            for (const { p, c } of profits) {
                if (totalItems >= k) break;
                const take = Math.min(c, k - totalItems);
                currentProfit += take * p;
                totalItems += take;
            }

            if (currentProfit > maxProfit) {
                maxProfit = currentProfit;
            }
        }
    }

    console.log(maxProfit);
