function solve(n, m, k, lines) {
    // Parse the input
    // lines[0] is the first line with n, m, k
    // Then for each planet i (0 to n-1):
    //   lines[1 + i * (1 + m)] is the planet name
    //   lines[1 + i * (1 + m) + 1] to lines[1 + i * (1 + m) + m] are the m items

    const planets = [];
    let idx = 1;
    for (let i = 0; i < n; i++) {
        const planetName = lines[idx];
