    // We want to maximize profit with at most k items
    // For each item type, we can buy some quantity from planet i and sell on planet j
    // Profit per item of type t when buying on i and selling on j: b[j][t] - a[i][t]
    // We can buy up to c[i][t] items of type t on planet i
    // Total items bought <= k

    // This is a bounded knapsack problem where:
    // - We have m item types
    // - For each type t, we can buy 0 to min(c[i][t], k) items
    // - Each item of type t has profit p[t] = b[j][t] - a[i][t]
    // - We want to maximize total profit with total items <= k

    // Since m and k are up to 100, we can use DP
    // dp[w] = max profit using exactly w items (or at most w items)

    let maxProfit = 0;

    for (let buyPlanet = 0; buyPlanet < n; buyPlanet++) {
        for (let sellPlanet = 0; sellPlanet < n; sellPlanet++) {
