            const limits = [];
            for (let t = 0; t < m; t++) {
                const profit = planets[sellPlanet].items[t].b - planets[buyPlanet].items[t].a;
                const limit = planets[buyPlanet].items[t].c;
                profits.push(profit);
                limits.push(limit);
            }

            // DP: dp[w] = max profit with w items
            const dp = new Array(k + 1).fill(0);

            // For each item type, we can add 0 to limit items
            // This is a bounded knapsack. We can use binary decomposition or just iterate.
            // Since k <= 100 and m <= 100, and limits <= 100, we can do:
            // For each type, for w from k down to 0, for count from 1 to min(limit, k-w):
            //   dp[w + count] = max(dp[w + count], dp[w] + count * profit)
            // But this is O(m * k * limit) = 100 * 100 * 100 = 1e6 which is fine.

            // Actually, let's use a more efficient approach with binary decomposition or just simple iteration
            // Simple approach: for each type, update dp
            for (let t = 0; t < m; t++) {
