    const firstLine = lines[0].split(' ').map(Number);
    const n = firstLine[0];
    const m = firstLine[1];
    const k = firstLine[2];

    let idx = 1;
    const planets = [];

    for (let i = 0; i < n; i++) {
        const name = lines[idx];
        idx++;
        const items = [];
        for (let j = 0; j < m; j++) {
            const parts = lines[idx].split(' ').map(Number);
            idx++;
            items.push({ a: parts[0], b: parts[1], c: parts[2] });
        }
        planets.push({ name, items });
    }

    // For each pair of planets (buy from i, sell to j), i != j
    // We want to maximize profit with at most k items.
    // For each item type, we can buy some quantity from planet i and sell on planet j.
    // Profit per item of type t: b_jt - a_it
    // We can buy at most c_it items of type t from planet i.
    // Total items bought <= k.

    // This is a bounded knapsack problem where:
    // - We have m "item types"
    // - For each type t, we can take 0 to c_it items
    // - Each item of type t has profit p_t = b_jt - a_it
    // - We want to maximize total profit with total count <= k

    // Since m, k <= 100, and c_it <= 100, we can use DP.
    // dp[x] = max profit using exactly x items (or at most x items)
    // We'll use dp[x] = max profit with x items total.

    let maxProfit = 0;

    for (let buyPlanet = 0; buyPlanet < n; buyPlanet++) {
        for (let sellPlanet = 0; sellPlanet < n; sellPlanet++) {
            if (buyPlanet === sellPlanet) continue;

            const buyItems = planets[buyPlanet].items;
            const sellItems = planets[sellPlanet].items;

            // dp[x] = max profit with x items
            const dp = new Array(k + 1).fill(-Infinity);
            dp[0] = 0;

            for (let t = 0; t < m; t++) {
                const maxBuy = buyItems[t].c;
                const profitPerItem = sellItems[t].b - buyItems[t].a;

                if (maxBuy === 0) continue;

                // New dp array for this item type
                const newDp = new Array(k + 1).fill(-Infinity);
                for (let x = 0; x <= k; x++) {
                    if (dp[x] === -Infinity) continue;
                    // Take 0 items of this type
                    newDp[x] = Math.max(newDp[x], dp[x]);
                    // Take q items of this type, q from 1 to min(maxBuy, k - x)
                    const maxQ = Math.min(maxBuy, k - x);
                    for (let q = 1; q <= maxQ; q++) {
                        const newProfit = dp[x] + q * profitPerItem;
                        if (newProfit > newDp[x + q]) {
                            newDp[x + q] = newProfit;
                        }
                    }
                }
                for (let x = 0; x <= k; x++) {
                    dp[x] = newDp[x];
                }
            }

            // Find max profit
            for (let x = 0; x <= k; x++) {
                if (dp[x] > maxProfit) {
                    maxProfit = dp[x];
                }
            }
        }
    }

    console.log(maxProfit);
}
