    const firstLine = lines[0].split(' ').map(Number);
    const n = firstLine[0];
    const m = firstLine[1];
    const k = firstLine[2];

    let index = 1;
    const planets = [];

    for (let i = 0; i < n; i++) {
        // Planet name
        const planetName = lines[index];
        index++;

        const items = [];
        for (let j = 0; j < m; j++) {
            const parts = lines[index].split(' ').map(Number);
            const a = parts[0];
            const b = parts[1];
            const c = parts[2];
            items.push({ a, b, c });
            index++;
        }

        planets.push({ name: planetName, items });
    }

    // We need to find the maximum profit.
    // Profit = sum over items sold (sell_price * count) - sum over items bought (buy_price * count)
    // We buy on one planet (say planet p) and sell on another planet (say planet q), p != q.
    // For each item type j, if we buy x_j items on planet p and sell them on planet q,
    // the profit for that item type is x_j * (b_qj - a_pj).
    // Constraints:
    //   0 <= x_j <= c_pj (buy limit on planet p for item j)
    //   sum x_j <= k (ship capacity)
    //   x_j must be non-negative integers.
    //
    // Note: We can choose to not buy anything (profit 0).
    // Also, we can only sell items we bought. Since we buy on one planet and sell on another,
    // and the problem says "buy some number of items on one of the planets, and then sell the bought items on another planet",
    // it implies we buy a set of items on planet p and sell all of them on planet q.
    //
    // So for a fixed pair (p, q) with p != q, we have a knapsack problem:
    //   Items: m types
    //   For each type j:
    //     weight = 1 (each item takes 1 unit of capacity)
    //     value = b_qj - a_pj
    //     max quantity = c_pj
    //   Capacity = k
    //
    // We want to maximize total value. If value is negative, we wouldn't buy that item.
    //
    // Since m, k <= 100, and c_pj <= 100, we can use a DP approach.
    // DP[i][w] = max profit using first i item types with total weight w.
    // But since each item type can be taken multiple times (up to c_pj), this is a bounded knapsack.
    //
    // Alternatively, we can think of it as: for each item type j, we can take 0 to c_pj items.
    // The total number of items is at most k.
    //
    // Let's use a 1D DP array of size k+1.
    // dp[w] = max profit with total weight w.
    // Initialize dp[0] = 0, dp[w] = -infinity for w > 0.
    //
    // For each item type j:
    //   For w from k down to 0:
    //     For count from 1 to min(c_pj, k - w):
    //       dp[w + count] = max(dp[w + count], dp[w] + count * (b_qj - a_pj))
    //
    // But this might be O(m * k * c_pj) which is 100 * 100 * 100 = 1e6 per pair.
    // Number of pairs is n*(n-1) <= 10*9 = 90.
    // Total operations: 90 * 1e6 = 9e7, which might be borderline in JS but should be okay.
    //
    // Actually, we can optimize the inner loop using a technique for bounded knapsack,
    // but given the constraints, the straightforward approach should work.
    //
    // Let's implement it.

    let maxProfit = 0;

    for (let p = 0; p < n; p++) {
        for (let q = 0; q < n; q++) {
            if (p === q) continue;

            // dp[w] = max profit with total weight w
            const dp = new Array(k + 1).fill(-Infinity);
            dp[0] = 0;

            for (let j = 0; j < m; j++) {
                const buyPrice = planets[p].items[j].a;
                const sellPrice = planets[q].items[j].b;
                const maxCount = planets[p].items[j].c;
                const profitPerItem = sellPrice - buyPrice;

                // If profitPerItem is negative, we wouldn't buy this item, so skip.
                // But even if negative, we might still consider it if we have to fill capacity? No, we can always choose 0.
                // So if profitPerItem <= 0, we can skip this item type entirely (taking 0 is best).
                if (profitPerItem <= 0) {
                    continue;
                }

                // For each possible weight from k down to 0
                for (let w = k; w >= 0; w--) {
                    if (dp[w] === -Infinity) continue;
                    // We can add up to maxCount items of type j
                    const maxAdd = Math.min(maxCount, k - w);
                    for (let count = 1; count <= maxAdd; count++) {
                        const newWeight = w + count;
                        const newProfit = dp[w] + count * profitPerItem;
                        if (newProfit > dp[newWeight]) {
                            dp[newWeight] = newProfit;
                        }
                    }
                }
            }

            // Find the max profit in dp
            for (let w = 0; w <= k; w++) {
                if (dp[w] > maxProfit) {
                    maxProfit = dp[w];
                }
            }
        }
    }

    console.log(maxProfit);
});
