```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
});

const lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const tokens = lines.join(' ').split(/\s+/).filter(t => t.length > 0);
    let idx = 0;

    const n = parseInt(tokens[idx++]);
    const m = parseInt(tokens[idx++]);
    const k = parseInt(tokens[idx++]);

    // planets[i][j] = { a, b, c }
    const planets = [];
    for (let i = 0; i < n; i++) {
        // skip planet name
        idx++; // planet name
        const planet = [];
        for (let j = 0; j < m; j++) {
            const a = parseInt(tokens[idx++]);
            const b = parseInt(tokens[idx++]);
            const c = parseInt(tokens[idx++]);
            planet.push({ a, b, c });
        }
        planets.push(planet);
    }

    // For each pair of planets (buy from i, sell to j), i != j
    // We want to maximize profit = sum over items of (sell_price - buy_price) * qty
    // subject to:
    //   qty_j <= c_ij (buy limit on planet i for item j)
    //   sum_j qty_j <= k
    //   qty_j >= 0, integer

    // For a fixed pair (i, j), the profit per item of type t is (b_jt - a_it)
    // We should buy items with the highest positive profit first.

    let maxProfit = 0;

    for (let buyPlanet = 0; buyPlanet < n; buyPlanet++) {
        for (let sellPlanet = 0; sellPlanet < n; sellPlanet++) {
            if (buyPlanet === sellPlanet) continue;

            // Calculate profit per item for each item type
            const profits = [];
            for (let t = 0; t < m; t++) {
                const buyPrice = planets[buyPlanet][t].a;
                const sellPrice = planets[sellPlanet][t].b;
                const maxQty = planets[buyPlanet][t].c;
                const profitPerItem = sellPrice - buyPrice;
                if (profitPerItem > 0 && maxQty > 0) {
                    profits.push({ profit: profitPerItem, maxQty });
                }
            }

            // Sort by profit descending
            profits.sort((x, y) => y.profit - x.profit);

            let totalProfit = 0;
            let remainingCapacity = k;

            for (const item of profits) {
                if (remainingCapacity <= 0) break;
                const qty = Math.min(item.maxQty, remainingCapacity);
                totalProfit += qty * item.profit;
                remainingCapacity -= qty;
            }

            if (totalProfit > maxProfit) {
                maxProfit = totalProfit;
            }
        }
    }

    console.log(maxProfit);
});
